// Some portions generated by Codex
package org.eclipse.rdf4j.sail.memory;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.List;
import java.util.Objects;
import java.util.Random;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import org.eclipse.rdf4j.common.iteration.Iterations;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.RDF;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.TupleQuery;
import org.eclipse.rdf4j.query.explanation.Explanation;
import org.eclipse.rdf4j.repository.Repository;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.junit.jupiter.api.Test;

/**
 * Pins the join order in the optimized query plan of a {@code FILTER NOT EXISTS} query over a two-graph dataset. The
 * backing data is synthetic and created in the test.
 * <p>
 * The query selects every group that carries a label and has no link of a particular type pointing back at it, and
 * projects three further variables that the {@code WHERE} clause never binds — always-unbound elements in the
 * projection below the {@code DISTINCT}. What is asserted is the shape of the optimized plan: that the
 * {@code NOT EXISTS} stays a {@code Filter} whose condition is a {@code Not}/{@code Exists} over a {@code Join} rather
 * than being rewritten into an anti-join, and the order in which the statement patterns inside and outside the
 * {@code Exists} are joined. Inside the {@code Exists} the {@code ex:memberOf} pattern is planned first, because
 * {@code ?group} is already bound by the outer join and so anchors that pattern to the handful of links belonging to
 * the current group — even though the {@code rdf:type} pattern has the lower raw cardinality (283 vs 418). That choice
 * is a deterministic function of the seeded dataset's cardinalities, and a change in it is a real change in how this
 * query is planned. The unit-level counterpart of this assertion is
 * {@code QueryJoinOptimizerTest#notExistsJoinOrderAccountsForVarsBoundByTheFilterArgument}.
 * <p>
 * All IRIs use the generic {@code http://example.org/ns/} namespace.
 */
class FilterNotExistsJoinOrderExplainTest {

	private static final String MODEL_NAMESPACE = "http://example.org/ns/model/";
	private static final String DATA_GRAPH = "http://example.org/ns/graph/DataContext";
	private static final String INFERENCE_GRAPH = "http://example.org/ns/graph/InferenceContext";
	private static final String GROUP_NAMESPACE = "http://example.org/ns/group/";
	private static final String LINK_NAMESPACE = "http://example.org/ns/link/";
	private static final String ITEM_NAMESPACE = "http://example.org/ns/item/";

	private static final int GROUP_COUNT = 200;
	private static final double ASSOCIATED_FRACTION = 0.60;
	private static final double LINK_FRACTION = 0.70;
	private static final int MIN_LINKS = 1;
	private static final int MAX_LINKS = 5;
	private static final int NOISE_ITEM_COUNT = 400;
	private static final long SEED = 42L;

	private static final String QUERY = "PREFIX ex: <" + MODEL_NAMESPACE + ">\n"
			+ "SELECT DISTINCT ?group ?label ?extra1 ?extra2 ?extra3\n"
			+ "FROM <" + DATA_GRAPH + ">\n"
			+ "FROM <" + INFERENCE_GRAPH + ">\n"
			+ "WHERE {\n"
			+ "  ?group a ex:Group ; ex:label ?label .\n"
			+ "  FILTER NOT EXISTS {\n"
			+ "    ?typedLink ex:memberOf ?group .\n"
			+ "    ?typedLink a ex:Link .\n"
			+ "  }\n"
			+ "}";

	@Test
	void pinsOptimizedPlanForGroupNotExistsDataset() {
		Repository repo = new SailRepository(new MemoryStore());
		repo.init();
		try {
			int expectedResults;
			try (RepositoryConnection connection = repo.getConnection()) {
				expectedResults = populateFixture(connection);
			}
			try (RepositoryConnection connection = repo.getConnection()) {
				TupleQuery query = connection.prepareTupleQuery(QUERY);

				Explanation optimized = query.explain(Explanation.Level.Optimized);
				String plan = optimized.toString();

				// The NOT EXISTS stays a Filter with a Not/Exists condition instead of being rewritten.
				assertThat(plan).contains("Filter").contains("Not").contains("Exists");

				// The plan lists the statement patterns of the Exists block first (the condition is printed before
				// the filter's argument), then those of the outer join.
				assertThat(predicatesInPlanOrder(plan)).containsExactly(
						MODEL_NAMESPACE + "memberOf",
						RDF.TYPE.stringValue(),
						RDF.TYPE.stringValue(),
						MODEL_NAMESPACE + "label");

				List<BindingSet> results = Iterations.asList(connection.prepareTupleQuery(QUERY).evaluate());
				assertThat(results).hasSize(expectedResults);
			}
		} finally {
			repo.shutDown();
		}
	}

	private static int populateFixture(RepositoryConnection connection) {
		ValueFactory vf = SimpleValueFactory.getInstance();
		IRI groupType = vf.createIRI(MODEL_NAMESPACE, "Group");
		IRI itemType = vf.createIRI(MODEL_NAMESPACE, "Item");
		IRI linkType = vf.createIRI(MODEL_NAMESPACE, "Link");
		IRI otherLinkType = vf.createIRI(MODEL_NAMESPACE, "OtherLink");
		IRI label = vf.createIRI(MODEL_NAMESPACE, "label");
		IRI memberOf = vf.createIRI(MODEL_NAMESPACE, "memberOf");
		IRI dataGraph = vf.createIRI(DATA_GRAPH);
		IRI inferenceGraph = vf.createIRI(INFERENCE_GRAPH);
		Random random = new Random(SEED);

		int groupsWithLink = 0;
		connection.begin();
		try {
			for (int g = 0; g < GROUP_COUNT; g++) {
				IRI group = vf.createIRI(GROUP_NAMESPACE + "group" + g);
				connection.add(group, RDF.TYPE, groupType, dataGraph);
				connection.add(group, label, vf.createLiteral("label-" + g), dataGraph);

				if (random.nextDouble() >= ASSOCIATED_FRACTION) {
					continue;
				}
				int linkCount = MIN_LINKS + random.nextInt(MAX_LINKS - MIN_LINKS + 1);
				boolean sawLink = false;
				for (int a = 0; a < linkCount; a++) {
					IRI link = vf.createIRI(LINK_NAMESPACE + "assoc" + g + "-" + a);
					connection.add(link, memberOf, group, dataGraph);
					if (random.nextDouble() < LINK_FRACTION) {
						connection.add(link, RDF.TYPE, linkType, inferenceGraph);
						sawLink = true;
					} else {
						connection.add(link, RDF.TYPE, otherLinkType, inferenceGraph);
					}
				}
				if (sawLink) {
					groupsWithLink++;
				}
			}

			for (int n = 0; n < NOISE_ITEM_COUNT; n++) {
				IRI item = vf.createIRI(ITEM_NAMESPACE + "item" + n);
				connection.add(item, RDF.TYPE, itemType, dataGraph);
				connection.add(item, label, vf.createLiteral("label-item-" + n), dataGraph);
			}

			connection.commit();
		} catch (RuntimeException e) {
			connection.rollback();
			throw e;
		}
		return GROUP_COUNT - groupsWithLink;
	}

	private static List<String> predicatesInPlanOrder(String plan) {
		Pattern valuePattern = Pattern.compile("p: Var \\(name=[^,]*, value=([^,]*),");
		return plan.lines().map(line -> {
			Matcher matcher = valuePattern.matcher(line);
			return matcher.find() ? matcher.group(1) : null;
		}).filter(Objects::nonNull).toList();
	}
}
